-- Question-scoped anonymous browser contributors; no cross-question player identifier.
CREATE TABLE biblillion_cloud_rankings(question_id TEXT PRIMARY KEY,ranking_json TEXT NOT NULL);
CREATE TABLE biblillion_cloud_contributions(question_id TEXT NOT NULL,contributor_hash TEXT NOT NULL,answer TEXT NOT NULL,updated_at TEXT NOT NULL,PRIMARY KEY(question_id,contributor_hash));
CREATE INDEX biblillion_cloud_answers ON biblillion_cloud_contributions(question_id,answer);
